<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { api, post } from '../api'
import LegacyIcon from './LegacyIcon.vue'
interface Settings { api_token?: string; mode: 'local' | 'cloud'; api_base_url: string; local_cli_path: string; model_download_source: 'huggingface' | 'modelscope'; model_download_endpoint: string; model_version: 'pipeline' | 'vlm'; language: string; enable_formula: boolean; enable_table: boolean; is_ocr: boolean; allow_local_model_download: boolean }
interface Payload { settings: Settings; api_token_set: boolean; local_cli?: { found: boolean; command: string; path: string; source?: string } }
const props = withDefaults(defineProps<{ pending?: unknown; revision?: number }>(), { revision: 0 })
const emit = defineEmits<{ change: [value: Settings]; loaded: [value: Settings] }>()
const defaults: Settings = { mode: 'local', api_base_url: 'https://mineru.net', local_cli_path: '', model_download_source: 'huggingface', model_download_endpoint: '', model_version: 'pipeline', language: 'auto', enable_formula: true, enable_table: true, is_ocr: false, allow_local_model_download: false }
const settings = reactive<Settings>({ ...defaults })
const payload = ref<Payload | null>(null)
const loading = ref(true)
const error = ref('')
const showToken = ref(false)
const tokenTouched = ref(false)
const testing = ref(false)
const testResult = ref<{ ok: boolean; message: string } | null>(null)
const downloadType = ref<'pipeline' | 'vlm' | 'all'>('pipeline')
const download = ref<{ state: string; lines: string[]; message: string } | null>(null)
let timer: ReturnType<typeof setInterval> | undefined
let cursor = 0
function assign(next: Settings) { Object.assign(settings, defaults, next) }
async function load() { loading.value = true; error.value = ''; try { const live = await api<Payload>('/api/settings/mineru'); payload.value = live; assign((props.pending as Settings | undefined) ?? live.settings); emit('loaded', live.settings) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'MinerU 设置加载失败' } finally { loading.value = false } }
onMounted(load); watch(() => props.revision, load); onUnmounted(() => { if (timer) clearInterval(timer) })
function changed() { emit('change', { ...settings }) }
function patch<K extends keyof Settings>(key: K, value: Settings[K]) { settings[key] = value; testResult.value = null; changed() }
async function test() { testing.value = true; testResult.value = null; try { testResult.value = await post<{ ok: boolean; message: string }>('/api/settings/mineru/test', { ...settings, ...(tokenTouched.value ? {} : { api_token: undefined }) }) } catch (cause) { testResult.value = { ok: false, message: cause instanceof Error ? cause.message : '连接测试失败' } } finally { testing.value = false } }
function poll() { if (timer) clearInterval(timer); timer = setInterval(async () => { try { const next = await api<{ state: string; lines?: string[]; next_cursor?: number; message?: string }>(`/api/settings/mineru/models/download/status?cursor=${cursor}`); cursor = next.next_cursor ?? cursor; if (download.value) download.value = { state: next.state, lines: [...download.value.lines, ...(next.lines || [])].slice(-100), message: next.message || '' }; if (next.state !== 'running' && timer) { clearInterval(timer); timer = undefined } } catch { /* transient network error */ } }, 1000) }
async function startDownload() { try { const result = await post<{ ok: boolean; message?: string }>('/api/settings/mineru/models/download', { model_type: downloadType.value, source: settings.model_download_source, endpoint: settings.model_download_endpoint, local_cli_path: settings.local_cli_path }); if (!result.ok) { download.value = { state: 'failed', lines: [], message: result.message || '下载失败' }; return }; cursor = 0; download.value = { state: 'running', lines: [], message: '' }; poll() } catch (cause) { download.value = { state: 'failed', lines: [], message: cause instanceof Error ? cause.message : '下载失败' } }
}
async function cancelDownload() { await post('/api/settings/mineru/models/download/cancel', {}).catch(() => null) }
</script>
<template><div class="mineru-settings"><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="legacy-settings-loading">加载中…</p><template v-else><section class="legacy-setting-section"><header><h2>解析后端</h2><p>选择 PDF 解析运行位置。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>模式</h3><p>{{ settings.mode === 'cloud' ? '文档将上传到 mineru.net 解析。' : '在本机使用 MinerU 安装进行解析。' }}</p></div><div class="mineru-mode"><button :class="{ active: settings.mode === 'local' }" @click="patch('mode', 'local')">本地</button><button :class="{ active: settings.mode === 'cloud' }" @click="patch('mode', 'cloud')">云端 API</button></div></div></div></section><template v-if="settings.mode === 'local'"><section class="legacy-setting-section"><header><h2>本地安装</h2><p>DeepTutor 服务进程必须能访问 MinerU CLI。官方建议预留至少 20 GB 磁盘。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>CLI 路径</h3><p>{{ payload?.local_cli?.found ? `已检测：${payload.local_cli.command}` : '可留空自动检测，或填写 mineru 可执行文件路径。' }}</p></div><input v-model="settings.local_cli_path" class="legacy-setting-number wide" placeholder="mineru" @input="patch('local_cli_path', ($event.target as HTMLInputElement).value)"></div><div class="legacy-setting-row"><div><h3>允许自动下载模型</h3><p>默认关闭。关闭时，本地解析会给出指引，而不会静默下载大型模型。</p></div><button role="switch" aria-label="允许自动下载模型" :aria-checked="settings.allow_local_model_download" class="legacy-toggle" :class="{ on: settings.allow_local_model_download }" @click="patch('allow_local_model_download', !settings.allow_local_model_download)"><span /></button></div><div class="legacy-setting-row"><div><h3>下载来源</h3></div><select v-model="settings.model_download_source" @change="changed"><option value="huggingface">HuggingFace</option><option value="modelscope">ModelScope</option></select></div><div v-if="settings.model_download_source === 'huggingface'" class="legacy-setting-row"><div><h3>下载地址</h3></div><input v-model="settings.model_download_endpoint" class="legacy-setting-number wide" placeholder="https://huggingface.co" @input="changed"></div><div class="legacy-setting-row"><div><h3>下载模型</h3><p>在服务器上显式下载模型权重。</p></div><div class="mineru-download"><select v-model="downloadType" :disabled="download?.state === 'running'"><option value="pipeline">pipeline</option><option value="vlm">vlm</option><option value="all">all</option></select><button v-if="download?.state === 'running'" @click="cancelDownload">取消</button><button v-else class="primary" @click="startDownload">下载</button></div></div><div v-if="download" class="mineru-job" :class="download.state"><p>{{ download.state === 'running' ? '正在下载模型…' : download.message || download.state }}</p><pre v-if="download.lines.length">{{ download.lines.join('\n') }}</pre></div></div></section></template><template v-else><section class="legacy-setting-section"><header><h2>云端 API</h2></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>API 地址</h3></div><input v-model="settings.api_base_url" class="legacy-setting-number wide" aria-label="API 地址" placeholder="https://mineru.net" @input="changed"></div><div class="legacy-setting-row"><div><h3>API Token</h3><p>{{ payload?.api_token_set ? '已保存 Token，输入以替换；留空则保留。' : '尚未保存 Token。' }}</p></div><div class="mineru-token"><input v-model="settings.api_token" :type="showToken ? 'text' : 'password'" :placeholder="payload?.api_token_set ? '••••••••••••' : '粘贴 API Token'" aria-label="API Token" autocomplete="new-password" @input="tokenTouched = true; changed()"><button :aria-label="showToken ? '隐藏 API Token' : '显示 API Token'" @click="showToken = !showToken">{{ showToken ? '隐藏' : '显示' }}</button></div></div><div class="legacy-setting-row"><div><h3>测试连接</h3><p>验证 Token，不消耗解析额度。</p></div><div class="mineru-test"><span v-if="testResult" :class="testResult.ok ? 'ok' : 'bad'">{{ testResult.message }}</span><button :disabled="testing" @click="test">{{ testing ? '测试中…' : '测试' }}</button></div></div></div></section></template><section class="legacy-setting-section"><header><h2>解析选项</h2><p>转发给 MinerU 处理每份文档。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>模型版本</h3><p>pipeline 更快，vlm 是视觉语言模型。</p></div><select v-model="settings.model_version" @change="changed"><option value="pipeline">pipeline</option><option value="vlm">vlm</option></select></div><div class="legacy-setting-row"><div><h3>语言</h3><p>使用 auto 自动检测文档语言。</p></div><input v-model="settings.language" class="legacy-setting-number" placeholder="auto" @input="changed"></div><div class="legacy-setting-row"><div><h3>提取公式</h3></div><button role="switch" aria-label="提取公式" :aria-checked="settings.enable_formula" class="legacy-toggle" :class="{ on: settings.enable_formula }" @click="patch('enable_formula', !settings.enable_formula)"><span /></button></div><div class="legacy-setting-row"><div><h3>提取表格</h3></div><button role="switch" aria-label="提取表格" :aria-checked="settings.enable_table" class="legacy-toggle" :class="{ on: settings.enable_table }" @click="patch('enable_table', !settings.enable_table)"><span /></button></div><div class="legacy-setting-row"><div><h3>强制 OCR</h3><p>将 PDF 视为扫描图片，速度较慢，仅用于无文本 PDF。</p></div><button role="switch" aria-label="强制 OCR" :aria-checked="settings.is_ocr" class="legacy-toggle" :class="{ on: settings.is_ocr }" @click="patch('is_ocr', !settings.is_ocr)"><span /></button></div></div></section></template></div></template>
